<script>
 import UiIcon from '#lib/components/UiIcon.svelte';
 import {lang} from '#lib/stores/lang.js';
 import {activityLabel} from '#lib/utils/activity-labels.js';
 import {placeStudent,classroomSlots,fillSeats,parseClassroom,classroomDeskPosition} from '#lib/utils/classroom-state.js';
 import {useUnsavedChanges,confirmDiscard,unsavedMessage} from '#lib/utils/unsaved.js';
 let students=[],seating={},count=12,capacity=2,layout='rows',title='';
 let draftCount=12,draftCapacity=2,draftLayout='rows',names='',selected=null,tab='room',message='',dirty=false;
 let past=[],future=[],fileInput;
 $: ui=key=>activityLabel($lang,key);
 $: slots=classroomSlots(count,capacity);
 $: present=students.filter(s=>!s.absent);
 $: seatedIds=new Set(Object.values(seating));
 $: waiting=present.filter(s=>!seatedIds.has(s.id));
 $: chosen=students.find(s=>s.id===selected&&!s.absent);
 useUnsavedChanges(()=>dirty,()=>$lang);
 function state(){return structuredClone({students,seating,count,capacity,layout,title,names});}
 function restore(s){({students,seating,count,capacity,layout,title,names=''}=s);draftCount=count;draftCapacity=capacity;draftLayout=layout;selected=null;dirty=true;}
 function remember(){past=[...past.slice(-39),state()];future=[];dirty=true;message='';}
 function undo(){if(!past.length)return;future=[state(),...future];const s=past.at(-1);past=past.slice(0,-1);restore(s);}
 function redo(){if(!future.length)return;past=[...past,state()];const s=future[0];future=future.slice(1);restore(s);}
 function add(){const list=names.split('\n').map(s=>s.trim().slice(0,100)).filter(Boolean);if(!list.length)return;if(students.length+list.length>150){message=ui('limit');return;}remember();let next=Math.max(0,...students.map(s=>s.id))+1;students=[...students,...list.map(name=>({id:next++,name,absent:false}))];names='';}
 function remove(id){remember();students=students.filter(s=>s.id!==id);seating=Object.fromEntries(Object.entries(seating).filter(([,sid])=>sid!==id));if(selected===id)selected=null;}
 function absent(id){remember();students=students.map(s=>s.id===id?{...s,absent:!s.absent}:s);if(students.find(s=>s.id===id).absent){seating=Object.fromEntries(Object.entries(seating).filter(([,sid])=>sid!==id));if(selected===id)selected=null;}}
 function choose(id){selected=selected===id?null:id;if(selected!=null)tab='room';}
 function place(key){if(!chosen){selected=seating[key]??null;return;}remember();seating=placeStudent(seating,selected,key);selected=null;}
 function unseat(){if(!chosen)return;remember();seating=Object.fromEntries(Object.entries(seating).filter(([,id])=>id!==selected));selected=null;}
 function arrange(){remember();count=Math.max(1,Math.min(30,Math.round(Number(draftCount)||1)));capacity=Number(draftCapacity);layout=draftLayout;const valid=new Set(classroomSlots(count,capacity));seating=Object.fromEntries(Object.entries(seating).filter(([key])=>valid.has(key)));draftCount=count;}
 function fill(all=false){remember();seating=fillSeats(students,seating,slots,all);selected=null;}
 function clear(){remember();seating={};selected=null;}
 function download(){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify({type:'evrika-classroom',version:1,...state()},null,2)],{type:'application/json'}));a.href=url;a.download='evrika-classroom.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);dirty=false;}
 async function load(e){const file=e.currentTarget.files?.[0];e.currentTarget.value='';if(!file)return;try{if(file.size>500000)throw Error();const s=parseClassroom(JSON.parse(await file.text()));if(dirty&&!await confirmDiscard(unsavedMessage($lang)))return;remember();restore(s);dirty=false;}catch{message=ui('invalid');}}
 function position(i){return classroomDeskPosition(i,count,layout);}
</script>
<svelte:head><title>{ui('classroom')} · EvrikaEdu</title></svelte:head>
<div class="studio">
 <header class="activity-heading"><div><span class="eyebrow">EVRIKA LAB · 01</span><h1>{ui('classroom')}</h1><p>{ui('classHint')}</p></div><div class="file-actions"><button on:click={download}>{ui('save')}</button><button on:click={()=>fileInput.click()}>{ui('open')}</button><input hidden bind:this={fileInput} type="file" accept=".json,application/json" on:change={load}/></div></header>
 <p class="memory">{ui('memory')}</p>
 {#if students.length}<div class="summary"><span><b>{present.length}</b> {ui('present')}</span><span><b>{Object.keys(seating).length}</b> {ui('seated')}</span><span><b>{waiting.length}</b> {ui('waiting')}</span><span><b>{slots.length-Object.keys(seating).length}</b> {ui('free')}</span></div>{/if}
 {#if past.length||future.length}<div class="history-controls"><button disabled={!past.length} on:click={undo}><UiIcon name="back" size={16}/>{ui('undo')}</button><button disabled={!future.length} on:click={redo}><UiIcon name="arrow" size={16}/>{ui('redo')}</button></div>{/if}
 <div class="mobile-tabs"><button class:active={tab==='room'} on:click={()=>tab='room'}>{ui('room')}</button><button class:active={tab==='list'} on:click={()=>tab='list'}>{ui('list')} · {students.length}</button></div>
 <div class="workspace">
  <aside class:mobile-hidden={tab!=='list'}>
   <h2>{ui('list')} <span>{students.length}</span></h2>
   <label>{ui('className')}<input maxlength="100" bind:value={title} on:input={()=>dirty=true}/></label>
   <label>{ui('names')}<textarea rows="3" maxlength="15500" bind:value={names} on:input={()=>dirty=true}></textarea></label><button class="primary wide" on:click={add} disabled={!names.trim()}>{ui('add')}</button>
   {#if !students.length}<p class="empty">{ui('empty')}</p>{/if}
   <ul>{#each students as student (student.id)}<li class:absent={student.absent} class:selected={selected===student.id}>
    <button class="student-name" disabled={student.absent} on:click={()=>choose(student.id)} aria-pressed={selected===student.id}><b>{student.name}</b><small>{student.absent?ui('absent'):seatedIds.has(student.id)?ui('seated'):ui('waiting')}</small></button>
    <button class="status" aria-label={`${student.name}: ${ui(student.absent?'markPresent':'markAbsent')}`} title={ui(student.absent?'markPresent':'markAbsent')} on:click={()=>absent(student.id)}>{student.absent?'↩':'○'}</button><button aria-label={`${ui('remove')}: ${student.name}`} on:click={()=>remove(student.id)}>×</button>
   </li>{/each}</ul>
  </aside>
  <section class="room-panel" class:mobile-hidden={tab!=='room'}>
   <div class="room-heading"><h2>{title||ui('room')}</h2></div>
   <details><summary>{ui('room')} · {count} × {capacity}</summary><div class="layout-controls"><label>{ui('room')}<select bind:value={draftLayout}><option value="rows">{ui('rows')}</option><option value="groups">{ui('groups')}</option><option value="u">{ui('u')}</option></select></label><label>{ui('desks')}<input type="number" min="1" max="30" bind:value={draftCount}/></label><label>{ui('capacity')}<select bind:value={draftCapacity}>{#each [1,2,4,6] as n}<option value={n}>{n}</option>{/each}</select></label><button class="primary" on:click={arrange}>{ui('apply')}</button></div><p>{ui('layoutHint')}</p></details>
   {#if !students.length}<div class="room-empty"><span><UiIcon name="team" size={24}/></span><div><h3>{ui('rosterStart')}</h3><p>{ui('rosterHint')}</p><button class="primary" on:click={()=>{tab='list';setTimeout(()=>document.querySelector('aside textarea')?.focus(),0);}}>{ui('openRoster')}</button></div></div>{/if}
   {#if students.length}<div class="tools"><button on:click={()=>fill(false)} disabled={!waiting.length||!slots.some(k=>!seating[k])}>{ui('fill')}</button><button on:click={()=>fill(true)} disabled={!present.length}>{ui('shuffle')}</button><button on:click={clear} disabled={!Object.keys(seating).length}>{ui('clear')}</button></div>{/if}
   {#if present.length>slots.length}<p class="warning" role="status">{ui('shortage')} {present.length-slots.length}</p>{/if}
   {#if chosen}<div class="selection" role="status"><div><small>{ui('selected')}</small><b>{chosen.name}</b><p>{ui('swapHint')}</p></div><div><button on:click={unseat} disabled={!seatedIds.has(selected)}>{ui('unseat')}</button><button on:click={()=>selected=null}>{ui('cancel')}</button></div></div>{/if}
   {#if waiting.length}<div class="waiting"><span>{ui('waiting')}</span>{#each waiting as s}<button class:active={selected===s.id} aria-pressed={selected===s.id} on:click={()=>choose(s.id)}>{s.name}</button>{/each}</div>{/if}
   {#if layout==='u'&&count>=5}<p class="pan-hint">↔ {ui('panHint')}</p>{/if}
   <div class="room-scroll"><div class="room-plan" class:wide-room={layout==='u'&&count>=5}><div class="board">{ui('board')}</div><div class="desks" class:islands={layout==='groups'} class:u={layout==='u'&&count>=5}>
    {#each Array(count) as _,i}<div class="desk" style={position(i)}><span>{ui('desk')} {i+1}</span><div class="seats" style={`--capacity:${capacity===1?1:2}`}>
     {#each Array(capacity) as _,j}{@const key=`${i}_${j}`}{@const student=students.find(s=>s.id===seating[key])}<button class:occupied={!!student} class:picked={student?.id===selected} aria-pressed={student?.id===selected} aria-label={`${ui('desk')} ${i+1}, ${ui('seat')} ${j+1}: ${student?.name||ui('free')}`} on:click={()=>place(key)}><span class="seat-number">{j+1}</span><span>{student?.name||'＋'}</span></button>{/each}
    </div></div>{/each}
   </div></div></div>
  </section>
 </div>{#if message}<p role="alert" class="warning">{message}</p>{/if}
</div>
<style>
 .history-controls{display:flex;gap:6px;justify-content:flex-end;margin:-4px 0 16px;}.history-controls button{display:flex;align-items:center;gap:7px;}.room-empty{display:flex;gap:12px;padding:18px;border:1px solid #e5d9f4;border-radius:16px;background:#f8f4fd;margin:16px 0;}.room-empty>span{width:42px;height:42px;display:grid;place-items:center;background:#eee1ff;color:#8b51d0;border-radius:12px;flex-shrink:0;}.room-empty h3{font-size:14px;font-weight:650;line-height:1.5;}.room-empty p{font-size:12px;line-height:1.7;color:#8b73a1;margin:5px 0 12px;}.pan-hint{display:none;}@media(max-width:767px){.pan-hint{display:block;font-size:11px;color:#806198;margin:12px 0;}.history-controls{justify-content:flex-start;margin:8px 0;position:sticky;top:68px;z-index:30;background:#ffffffed;border:1px solid #e8dcf2;border-radius:12px;padding:5px;width:max-content;max-width:100%;}}
 .studio{color:#332c45;--ink:#6447a0;}button{min-height:44px;padding:10px 14px;border:1px solid #ded5e9;background:#fff;border-radius:12px;font-size:12px;line-height:1.4;color:#554166;}button:hover{background:#f2ebfc;}button:disabled{opacity:.42;cursor:default;}button.primary{background:var(--color-primary);color:white;border-color:var(--color-primary);}.wide{width:100%;}.activity-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;}.eyebrow{font-size:10px;font-weight:800;letter-spacing:2px;color:#695182;}h1{font-size:30px;font-weight:750;line-height:1.2;margin:8px 0;}header p{font-size:14px;max-width:600px;line-height:1.7;color:#69577d;}.file-actions{display:flex;gap:8px;flex-wrap:wrap;}.memory{font-size:11px;color:#725b85;margin:16px 0;}.summary{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0;}.summary>span{background:#ffffffb0;padding:12px 18px;border-radius:14px;font-size:12px;}.summary b{font-size:21px;margin-right:6px;}.workspace{display:grid;grid-template-columns:290px minmax(0,1fr);gap:18px;}aside,.room-panel{background:#ffffffd9;border:1px solid #ffffff;border-radius:22px;padding:20px;min-width:0;}h2{font-size:17px;font-weight:700;}h2 span{font-size:12px;color:#897497;}label{display:flex;flex-direction:column;gap:7px;font-size:11px;font-weight:600;margin:16px 0;}input,textarea,select{width:100%;min-width:0;background:#fff;border:1px solid #ded5e9;border-radius:10px;padding:10px;color:#453251;}textarea{resize:vertical;}ul{margin-top:20px;max-height:600px;overflow:auto;}li{display:flex;align-items:center;border-bottom:1px solid #eee7f2;padding:5px 0;gap:4px;}li button{border:0;padding:8px;flex-shrink:0;}li.absent{background:#f4f0f5;}li.selected{background:#eee4fc;}.student-name{text-align:left;flex:1;min-width:0;background:transparent;overflow-wrap:anywhere;}.student-name b{display:block;font-weight:600;}.student-name small{color:#95829f;font-size:10px;}.status{color:#8963b8;}li>button:last-child{color:#b15f6a;}.empty{padding:30px 0;color:#96839f;font-size:13px;}.room-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;}details{margin:18px 0;background:#f5effa;border-radius:14px;padding:12px 15px;}summary{cursor:pointer;font-size:12px;font-weight:600;min-height:24px;}.layout-controls{display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:10px;}.layout-controls button{grid-column:1/-1;}details p{font-size:11px;color:#8a7399;line-height:1.6;margin-top:10px;}.tools{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:16px;}.tools button{font-size:11px;flex:1;}.warning{padding:14px;background:#fff0d8;color:#926128;border-radius:12px;font-size:13px;margin:12px 0;}.selection{border:1px solid #c9b1ed;background:#f0e7fb;padding:15px;border-radius:16px;margin-bottom:14px;}.selection small,.selection b{display:block;}.selection small{font-size:10px;color:#8a6ea7;}.selection p{font-size:11px;line-height:1.6;margin:7px 0;}.selection>div:last-child{display:flex;gap:6px;flex-wrap:wrap;}.waiting{display:flex;flex-wrap:wrap;gap:6px;margin:15px 0;}.waiting>span{width:100%;font-size:10px;color:#8a7399;}.waiting button{padding:7px 12px;font-size:11px;}.waiting .active{background:#7350ad;color:white;}.room-scroll{overflow:auto;padding:12px 2px;}.room-plan.wide-room{min-width:510px;}.board{width:65%;margin:0 auto 30px;background:#395c57;color:#d4eee5;border-radius:8px;border-bottom:5px solid #cab38e;text-align:center;letter-spacing:4px;font-size:10px;padding:12px;}.desks{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px 14px;}.desks.islands{gap:28px;}.desks.u{min-width:510px;}.desk{border:1px solid #d3c3e2;background:#eee5f5;border-radius:12px;padding:8px;min-width:0;}.desk>span{font-size:9px;text-transform:uppercase;letter-spacing:1px;color:#8a709e;display:block;margin-bottom:7px;}.seats{display:grid;grid-template-columns:repeat(var(--capacity),minmax(0,1fr));gap:5px;}.seats button{position:relative;padding:8px 4px;min-width:0;min-height:60px;overflow-wrap:anywhere;font-size:11px;line-height:1.35;background:#ffffff80;border-style:dashed;}.seats button.occupied{background:#fff;border-style:solid;color:#514061;box-shadow:0 2px 4px #34213d08;}.seats button.picked{background:#7350ad;color:white;outline:2px solid #b496db;}.seat-number{position:absolute;top:2px;left:5px;font-size:8px;color:#a792b6;}.mobile-tabs{display:none;}@media(max-width:1000px){.workspace{grid-template-columns:250px minmax(0,1fr);}.desks{grid-template-columns:repeat(2,minmax(0,1fr));}.desks.u{grid-template-columns:repeat(3,minmax(0,1fr));}.activity-heading{align-items:flex-start;}}@media(max-width:767px){h1{font-size:26px;}.activity-heading{display:block;}.file-actions{margin-top:15px;}.summary{display:grid;grid-template-columns:1fr 1fr;}.summary>span{padding:10px 12px;}.summary b{font-size:18px;}.workspace{display:block;}.mobile-tabs{display:flex;gap:6px;margin:12px 0;}.mobile-tabs button{flex:1;}.mobile-tabs .active{background:#7350ad;color:white;}.mobile-hidden{display:none;}aside,.room-panel{padding:14px;border-radius:18px;}.room-heading{align-items:flex-start;flex-direction:column;}.desks{gap:18px 10px;}.desks.islands{gap:22px 12px;}.seats button{font-size:12px;min-height:64px;}header p{font-size:13px;}.layout-controls{grid-template-columns:1fr 1fr;}.layout-controls label:first-child{grid-column:1/-1;}ul{max-height:none;}}
</style>
